/* crosswalk cards, r34. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34a"]=[{"q": "d(x, y) = |x − y| + 1 for x ≠ y, and 0 for x = y. Is d a distance on the line?", "a": "yes: all four conditions hold", "w": ["no: the triangle condition fails", "no: d is never 0", "no: d is not even"], "why": "The +1 adds to both sides of the triangle condition and never breaks it."}, {"q": "d(x, y) = (x − y)². Is d a distance on the line?", "a": "no: the triangle condition fails", "w": ["yes: all four conditions hold", "no: d can be negative", "no: d is not even"], "why": "d(0, 2) = 4 but d(0, 1) + d(1, 2) = 2."}, {"q": "A line reads |d(x, z) − d(y, z)| ≤ d(x, y). Which technique licenses it?", "a": "back-triangle", "w": ["ball-open", "keeps-limits", "open-family"], "why": "The triangle condition, used twice."}, {"q": "The points at distance less than 2 from x. What are they called?", "a": "the ball of reach 2 about x", "w": ["the closure of x", "an open cover of x", "the reach of x"], "why": "B(x, 2): all y with d(x, y) < 2."}, {"q": "On the line with |x − y|, is [0, 1) open?", "a": "no: no ball about 0 lies inside", "w": ["yes: it is a ball", "yes: its leftover is closed", "no: it is closed"], "why": "Every ball about 0 holds negative numbers."}, {"q": "A line reads “the overlap of U and V is open, since U and V are”. Which technique licenses it?", "a": "open-family", "w": ["ball-open", "pull-back", "closed-part"], "why": "Take the smaller of the two reaches."}, {"q": "xₙ = 1/n in (0, 1] with |x − y|. Does the list settle in (0, 1]?", "a": "no: it crowds, and 0 is not in the space", "w": ["yes: at 0", "yes: at 1", "no: it does not crowd"], "why": "A crowding list with nowhere to settle: (0, 1] is not complete."}, {"q": "A line reads “f⁻¹(V) is open for every open V, so f is continuous”. Which technique licenses it?", "a": "pull-back", "w": ["keeps-limits", "back-triangle", "closed-part"], "why": "Continuity at every point is open pull-backs."}, {"q": "A line reads “each (−1/n, 1/n) is open, so their overlap is open”. What is wrong?", "a": "only finite overlaps are sure to be open", "w": ["the sets are not balls", "the overlap is empty", "nothing: overlaps of opens are open"], "why": "The overlap is {0}, which is not open."}, {"q": "[0, 1] with |x − y|, inside the line. Which technique says it is complete?", "a": "closed-part", "w": ["keeps-limits", "open-family", "pull-back"], "why": "A closed part of a complete space is complete."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34b"]=[{"q": "A family holds ∅ and X, every union of members, and the overlap of two members. What is it?", "a": "a family of open sets", "w": ["a base", "an open cover", "a glued space"], "why": "The three conditions, and nothing about distance."}, {"q": "On the plane: straight distance and street distance. Which technique says they have the same open sets?", "a": "same-opens", "w": ["pull-back-chain", "two-parts", "glued-map"], "why": "Each ball of one holds a ball of the other."}, {"q": "A line reads (g ∘ f)⁻¹(W) = f⁻¹(g⁻¹(W)), open. Which technique is being proved?", "a": "pull-back-chain", "w": ["two-parts", "one-limit-apart", "same-opens"], "why": "A continuous map after a continuous map."}, {"q": "Sets U × V with U open in X and V open in Y. What are they called?", "a": "boxes", "w": ["bases", "balls", "covers"], "why": "The boxes make a base for the open sets of X × Y."}, {"q": "A map into X × Y has continuous left and right entries. Which technique says it is continuous?", "a": "two-parts", "w": ["pull-back-chain", "glued-map", "same-opens"], "why": "Pull-backs of boxes are overlaps of two open pull-backs."}, {"q": "Any two different points lie in two open sets that do not meet. What is the space said to do?", "a": "keep points apart", "w": ["be in one piece", "be complete", "be glued"], "why": "Then a list settles at one point at most."}, {"q": "X = {0, 1}, open sets ∅, {1}, {0, 1}. Does X keep points apart?", "a": "no: every open set holding 0 holds 1", "w": ["yes: {1} is open", "yes: X has two points", "no: X is not open"], "why": "The only open set about 0 is X."}, {"q": "A map g out of X/∼ with g ∘ q continuous. Which technique gives that g is continuous?", "a": "glued-map", "w": ["two-parts", "pull-back-chain", "one-limit-apart"], "why": "The open sets of X/∼ are those whose pull-back by q is open."}, {"q": "A line reads “every family of open sets comes from some distance”. What is wrong?", "a": "a family from a distance keeps points apart, and some do not", "w": ["every family does come from one", "distances make no open sets", "only the line has a distance"], "why": "{∅, {1}, {0, 1}} keeps no points apart."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34c"]=[{"q": "Two open, non-empty, separate parts whose union is X. What do they do to X?", "a": "split it", "w": ["cover it", "glue it", "join it by paths"], "why": "A space is in one piece when nothing splits it."}, {"q": "(0, 1) ∪ (2, 3). Is it in one piece?", "a": "no: (0, 1) and (2, 3) split it", "w": ["yes: it is a union of stretches", "yes: it is open", "no: it is not closed"], "why": "Both parts are open in the space and do not meet."}, {"q": "The fractions in [0, 1]. Are they in one piece?", "a": "no: an irrational between two of them splits them", "w": ["yes: any two are close", "yes: they are dense", "no: they are finite"], "why": "Below and above √2/2 are two open parts."}, {"q": "f continuous on [1, 3], f(1) = −2, f(3) = 5. Which technique, with one-piece-is-a-stretch, gives a root?", "a": "image-one-piece", "w": ["path-one-piece", "closure-one-piece", "stretch-one-piece alone"], "why": "f([1, 3]) is in one piece, so a stretch holding −2 and 5."}, {"q": "A continuous map γ from [0, 1] into X. What is it called?", "a": "a path in X", "w": ["a loop at γ(0)", "a split of X", "a stretch of X"], "why": "X is joined by paths when any two points are its ends."}, {"q": "A line reads “X is joined by paths, so X is in one piece”. Which technique licenses it?", "a": "path-one-piece", "w": ["image-one-piece", "sine-curve", "closure-one-piece"], "why": "A split would split the image of a path."}, {"q": "The graph of sin(1/x) for 0 < x ≤ 1, with {0} × [−1, 1]. Is it joined by paths?", "a": "no: it is in one piece and not joined by paths", "w": ["yes: it is in one piece", "no: it is not in one piece", "yes: each part is a path"], "why": "The sine-curve technique."}, {"q": "A in one piece, and A ⊆ B ⊆ closure of A. Which technique says B is in one piece?", "a": "closure-one-piece", "w": ["path-one-piece", "image-one-piece", "stretch-one-piece"], "why": "Adding limit points cannot split a piece."}, {"q": "A line reads “f is continuous and takes 0 and 2, so it takes 1”. What is missing?", "a": "that the inputs are in one piece", "w": ["that f is one-to-one", "that f is a path", "that 1 lies between 0 and 2"], "why": "On (0, 1) ∪ (2, 3), f can jump from 0 to 2."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34d"]=[{"q": "Every open cover of X has finitely many members that still cover X. What is X said to be?", "a": "finitely covered", "w": ["in one piece", "complete", "kept apart"], "why": "Its accepted name is compact."}, {"q": "(0, 1) covered by the sets (1/n, 1). Is there a finite part that covers?", "a": "no: finitely many miss points near 0", "w": ["yes: (1/2, 1) alone", "yes: two of them", "no: they are not open"], "why": "So (0, 1) is not finitely covered."}, {"q": "Is [0, 5] finitely covered?", "a": "yes: closed and bounded on the line", "w": ["no: it is not open", "no: it has endlessly many points", "yes: it is in one piece"], "why": "Closed-and-bounded technique."}, {"q": "Is [0, ∞) finitely covered?", "a": "no: it is not bounded", "w": ["yes: it is closed", "yes: it is in one piece", "no: it is not closed"], "why": "The cover by (−1, n) has no finite part."}, {"q": "A line reads “f is continuous and X finitely covered, so f(X) is finitely covered”. Which technique?", "a": "image-covered", "w": ["closed-part-covered", "covered-is-closed", "box-covered"], "why": "Pull back a cover of f(X), take a finite part."}, {"q": "A line reads “X and Y are finitely covered, so X × Y is”. Which technique?", "a": "box-covered", "w": ["products-choose", "image-covered", "closed-part-covered"], "why": "Two finite parts, one for each entry."}, {"q": "Every product of finitely covered spaces finitely covered implies every family of non-empty sets has a choosing function. Which technique?", "a": "products-choose", "w": ["box-covered", "covered-thread", "cover-reach"], "why": "Endless products spend the axiom of choice."}, {"q": "In a finitely covered space with a distance, every list has a thread that settles. Which technique?", "a": "covered-thread", "w": ["cover-reach", "keeps-limits", "closed-and-bounded"], "why": "On a closed stretch it is the settling-thread technique of rung 12."}, {"q": "A line reads “closed and bounded, so finitely covered” with the all-or-nothing distance on the whole numbers. What is wrong?", "a": "closed and bounded suffices only on the line", "w": ["the set is not bounded", "the set is not closed", "nothing: it is finitely covered"], "why": "Single points cover it, and no finitely many do."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34e"]=[{"q": "f is a bijection, f is continuous, and its reverse is continuous. What is f?", "a": "a same-shape map", "w": ["a covering", "a press", "a path"], "why": "Two spaces are the same shape when one exists."}, {"q": "The line and (−1, 1). Are they the same shape?", "a": "yes: x ↦ x/(1 + |x|) matches them", "w": ["no: one is bounded", "no: one is complete", "yes: both have a distance"], "why": "Boundedness and completeness are not shape-properties."}, {"q": "Is completeness a shape-property?", "a": "no: the line is complete and (−1, 1) is not", "w": ["yes: it is kept by every map", "yes: it needs only open sets", "no: no property is"], "why": "They are the same shape, one complete, one not."}, {"q": "Take any one point out of the line: two pieces. Out of the plane: one piece. What follows?", "a": "they are not the same shape", "w": ["they are the same shape", "the plane is not in one piece", "the line is finitely covered"], "why": "Point-out technique."}, {"q": "Wrapping [0, 1) round the circle by t ↦ (cos 2πt, sin 2πt). Is it a same-shape map?", "a": "no: its reverse breaks at (1, 0)", "w": ["yes: it is a continuous bijection", "no: it is not onto", "yes: both are in one piece"], "why": "Points just below (1, 0) go near 1, (1, 0) itself to 0."}, {"q": "A continuous bijection from a finitely covered space onto one that keeps points apart. Which technique says it is a same-shape map?", "a": "covered-matching", "w": ["kept-by-shape", "point-out", "same-shape"], "why": "Closed sets go to finitely covered, so closed, sets."}, {"q": "X same shape as Y, and X is in one piece. Which technique says Y is?", "a": "kept-by-shape", "w": ["point-out", "covered-matching", "image-one-piece alone"], "why": "In one piece is a statement about open sets."}, {"q": "The letters O and L, drawn thin. Are they the same shape?", "a": "no: one point out of L can leave two pieces", "w": ["yes: both are one stroke", "yes: both are in one piece", "no: O is not in one piece"], "why": "Every point out of O leaves one piece."}, {"q": "A line reads “a continuous bijection is a same-shape map”. What is wrong?", "a": "its reverse need not be continuous", "w": ["it need not be onto", "it is never continuous", "nothing: it is one"], "why": "Wrapping [0, 1) round the circle."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34f"]=[{"q": "A drawing on the sphere in one piece: V = 8, E = 12. What is F?", "a": "6", "w": ["4", "8", "2"], "why": "Sphere-drawing: V − E + F = 2."}, {"q": "Cutting an edge in two adds one corner and one edge. Which technique says the count is kept?", "a": "finer-cut", "w": ["sphere-drawing", "word-count", "sum-count"], "why": "+1 − 1 = 0."}, {"q": "V − E + F for any cutting of a closed surface S. What is it called?", "a": "the characteristic χ(S)", "w": ["the word of S", "the loop group of S", "the sides of S"], "why": "The same for every cutting."}, {"q": "The square sewn by x y x⁻¹ y⁻¹. Corner classes 1, pairs 2. What is χ?", "a": "0", "w": ["1", "2", "−1"], "why": "Word-count: V − n + 1 = 1 − 2 + 1."}, {"q": "A word has the letter x twice with the same arrow: x … x. What does that make the surface?", "a": "one-sided", "w": ["two-sided", "not closed", "the sphere"], "why": "Sewing x to x the same way puts a twist in."}, {"q": "χ(S) = 0, χ(T) = −2. What is χ(S summed with T)?", "a": "−4", "w": ["−2", "0", "−6"], "why": "Sum-count: 0 + (−2) − 2."}, {"q": "A two-sided closed surface with χ = −2. Which is it on the list?", "a": "two tori summed", "w": ["the sphere", "three cross-caps", "the torus"], "why": "Tori: χ = 2 − 2g, so g = 2."}, {"q": "A one-sided closed surface with χ = 1. Which is it on the list?", "a": "one cross-cap", "w": ["the sphere", "the torus", "two cross-caps"], "why": "Cross-caps: χ = 2 − k, so k = 1."}, {"q": "The picture frame: 16 − 32 + 16 = 0. A line reads “every solid with flat faces has V − E + F = 2”. What is wrong?", "a": "it holds only for solids shaped like a sphere", "w": ["the count of the frame is wrong", "the frame has curved faces", "nothing: the frame is not a solid"], "why": "The frame’s surface is a torus."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34g"]=[{"q": "A path from x₀ back to x₀. What is it called?", "a": "a loop at x₀", "w": ["a lift", "a slide", "a sheet"], "why": "Loops are multiplied by running one then the other."}, {"q": "In a space of vectors, every loop at x₀ slides to the loop that stays at x₀. Which technique?", "a": "straight-slide", "w": ["loop-group", "path-lift", "circle-loops"], "why": "Slide along straight segments to x₀."}, {"q": "The sliding classes of loops at x₀, with [γ][δ] = [γ · δ]. What do they form?", "a": "a group: the loop group", "w": ["a free group always", "a covering", "a family of open sets"], "why": "Loop-group technique; its accepted mark is π₁."}, {"q": "A path on the line with p ∘ γ̃ = γ for a path γ on the circle. What is γ̃?", "a": "a lift of γ", "w": ["a slide of γ", "the reverse of γ", "a loop at γ(0)"], "why": "Path-lift: exactly one from each start."}, {"q": "A loop on the circle lifts to a path from 0.25 to 3.25. What is its winding number?", "a": "3", "w": ["3.25", "0.25", "4"], "why": "w(γ) = γ̃(1) − γ̃(0)."}, {"q": "A line reads w(γ · δ) = w(γ) + w(δ). Which technique licenses it?", "a": "circle-loops", "w": ["covering-lift", "straight-slide", "path-lift"], "why": "The loop group of the circle is the whole numbers, products as sums."}, {"q": "p: line → circle. Each small arc pulls back to separate copies, each carried onto it. What is p?", "a": "a covering, with the copies as sheets", "w": ["a press", "a same-shape map", "a loop"], "why": "The line covers the circle."}, {"q": "z ↦ z² on the circle. What does it do to the whole numbers of the loop group?", "a": "n ↦ 2n", "w": ["n ↦ n²", "n ↦ n + 2", "n ↦ n"], "why": "One turn of z gives two turns of z²."}, {"q": "A line reads “every loop in the plane with a point out slides to its start”. What is wrong?", "a": "the loop round the missing point has winding 1", "w": ["the plane is not in one piece", "nothing: loops in the plane slide", "the space is not open"], "why": "Straight slides would pass through the missing point."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34h"]=[{"q": "A continuous map of the disc onto its rim that keeps every rim point. What is it called?", "a": "a press", "w": ["a covering", "a kept point", "a vector field"], "why": "The no-press technique says there is none."}, {"q": "Why is there no press of the disc onto its rim?", "a": "the rim loop, winding 1, would slide to a point", "w": ["the disc is not in one piece", "the rim is not closed", "the disc is not finitely covered"], "why": "No-press technique, through the loop group of the circle."}, {"q": "f maps the disc into itself, continuously. Which technique gives f(x) = x for some x?", "a": "kept-point", "w": ["no-press", "field-slide", "image-covered"], "why": "With no kept point, the ray from f(x) through x would press the disc."}, {"q": "A half turn of the ring 1 ≤ |z| ≤ 2. Does it keep a point?", "a": "no: the ring is not the disc", "w": ["yes: by the kept-point technique", "yes: the centre", "no: it is not continuous"], "why": "The kept-point technique needs the disc."}, {"q": "Each point x of the sphere gets a vector at right angles to x, continuously. What is it?", "a": "a vector field on the sphere", "w": ["a press of the sphere", "a covering of the sphere", "a loop on the sphere"], "why": "The hairy ball claim: it vanishes somewhere."}, {"q": "A field that never vanishes would slide the do-nothing map into x ↦ −x. Which technique?", "a": "field-slide", "w": ["kept-point", "no-press", "circle-loops"], "why": "Turn each point along its vector by a half circle."}, {"q": "Stir a cup of coffee and let it settle. What does the kept-point technique say?", "a": "some point of the surface is where it began, if the map is continuous", "w": ["every point is where it began", "no point stays", "the middle point stays"], "why": "A continuous map of the disc into itself."}, {"q": "A line reads “every continuous map of the circle into itself keeps a point”. What is wrong?", "a": "a quarter turn of the circle keeps none", "w": ["the circle is the disc", "nothing: the circle is finitely covered", "the circle has no rim"], "why": "The technique is for the disc."}, {"q": "f(x, y) = ((1 + y)/2, x/2) on the unit square. Is it sure to keep a point?", "a": "yes: it maps the square into itself", "w": ["no: it is not a same-shape map", "no: the square is not a disc", "yes: it is onto"], "why": "The square is the same shape as the disc."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34i"]=[{"q": "A word with no x next to x⁻¹. What is it called?", "a": "reduced", "w": ["a relation", "a presentation", "a loop"], "why": "Multiply by writing one after the other and cancelling."}, {"q": "x y y⁻¹ x. What is its reduced word?", "a": "x x", "w": ["x y x", "e", "y x"], "why": "Cancel y y⁻¹."}, {"q": "The reduced words in a set of letters form a group. Which technique?", "a": "free-group", "w": ["presented-map", "turn-about-count", "loop-group"], "why": "Each word acts on the reduced words as a shuffle."}, {"q": "⟨x, y | x y x⁻¹ y⁻¹⟩. What does it name?", "a": "the group of words in x and y where x y x⁻¹ y⁻¹ does nothing", "w": ["the free group on x and y", "the group of two members", "the circle’s loop group"], "why": "A presentation: letters and relations."}, {"q": "r ↦ quarter turn, f ↦ flip, and r⁴, f², f r f r do nothing in the square’s moves. Which technique gives one map?", "a": "presented-map", "w": ["free-group", "turn-about-count", "gluing technique"], "why": "Relations that hold give exactly one product-keeping map."}, {"q": "Two circles joined at a point. What is the loop group, by the gluing technique?", "a": "free on two letters", "w": ["pairs of whole numbers", "the whole numbers", "one member"], "why": "Each circle gives a letter, the overlap gives no relation."}, {"q": "The torus’s group with its letters allowed to change places. What is it?", "a": "pairs of whole numbers", "w": ["the whole numbers", "one member", "a group of two"], "why": "Turn-about-count: 2g whole numbers with g = 1."}, {"q": "The bottle’s group, letters changing places. Which member, other than e, done twice does nothing?", "a": "the class of x", "w": ["the class of y", "none", "the class of x y"], "why": "x y x y⁻¹ = e becomes 2x = 0."}, {"q": "A line reads “the loops of the figure eight change places”. What is wrong?", "a": "x y and y x are different reduced words", "w": ["the figure eight has one loop", "nothing: all loops commute", "x and y are not loops"], "why": "The group is free."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34j"]=[{"q": "g continuous to the line. Is {g > 3} open?", "a": "yes: by the strict-test technique", "w": ["no: it is closed", "only if g is one-to-one", "only if 3 is a value"], "why": "The pull-back of (3, ∞)."}, {"q": "g continuous to the line. Is {g = 0} open or closed?", "a": "closed", "w": ["open", "neither, always", "both, always"], "why": "Strict-test: g = c is closed."}, {"q": "A = [0, 1) on the line. What is the edge of A?", "a": "{0, 1}", "w": ["{1}", "[0, 1]", "∅"], "why": "Every open set about 0 or 1 meets A and its leftover."}, {"q": "A = {1/n}. What is its closure?", "a": "A with 0 added", "w": ["A", "[0, 1]", "∅"], "why": "0 is a limit of A."}, {"q": "A = the fractions in the line. What is the inside of A?", "a": "∅", "w": ["the fractions", "the line", "{0}"], "why": "Every stretch holds irrationals."}, {"q": "A point every open set about which meets A and its leftover. Which technique names it an edge point?", "a": "edge", "w": ["strict-test", "base-check", "pull-back"], "why": "The edge is closure minus inside."}, {"q": "Checking only pull-backs of stretches (c, d) to prove g continuous to the line. Which technique allows it?", "a": "base-check", "w": ["strict-test", "edge", "two-parts"], "why": "The stretches are a base for the line’s open sets."}, {"q": "The round-down: the pull-back of (½, 3/2). What is it?", "a": "[1, 2): not open, so it breaks at 1", "w": ["(1, 2): open", "{1}: closed", "∅: open"], "why": "A break shows as a pull-back that is not open."}, {"q": "A line reads “one open pull-back shows that f is continuous”. What is wrong?", "a": "every pull-back of an open set must be open", "w": ["pull-backs are always open", "only closed pull-backs count", "nothing: one is enough"], "why": "The round-down pulls (5.2, 5.8) back to ∅."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34k"]=[{"q": "The square sewn by x y x⁻¹ y⁻¹. Which surface?", "a": "the torus", "w": ["the bottle", "the cross-cap", "the sphere"], "why": "Two-sided, count 0."}, {"q": "The square sewn by x y x y⁻¹. Which surface?", "a": "the bottle", "w": ["the torus", "the cross-cap", "the sphere"], "why": "One-sided, count 0."}, {"q": "The square sewn by x y x y. Which surface?", "a": "the cross-cap", "w": ["the bottle", "the torus", "the sphere"], "why": "Square-cap: one-sided, count 1."}, {"q": "On the square torus, the line of slope 2/3 from a corner. How many times does it cross the left and right sides before closing?", "a": "3", "w": ["2", "5", "6"], "why": "Slope-loop: m = 3 in lowest terms."}, {"q": "On the square torus, the line of slope √2. Does it close?", "a": "no: its slope is not a fraction", "w": ["yes: after 2 crossings", "yes: after √2 crossings", "no: it leaves the square"], "why": "Slope-loop technique."}, {"q": "A word x A x B becomes z z A B⁻¹. What move is that?", "a": "the same-way move", "w": ["the bottle-sum", "a cancelling fold", "the handle-cap"], "why": "Cut along z, sew along x."}, {"q": "The bottle is two cross-caps summed. Which technique?", "a": "bottle-sum", "w": ["square-cap", "handle-cap", "slope-loop"], "why": "The same-way move on x y x y⁻¹."}, {"q": "A torus summed with a cross-cap. Which surface on the list?", "a": "three cross-caps summed", "w": ["a torus", "two cross-caps", "the bottle"], "why": "Handle-cap: count 0 + 1 − 2 = −1 = 2 − 3."}, {"q": "A line reads “the bottle has count 0, so it is the torus”. What is wrong?", "a": "the bottle is one-sided and the torus is not", "w": ["the bottle has count 1", "the torus has count 2", "nothing: count settles it"], "why": "Count and sides together settle the surface."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34l"]=[{"q": "A loop crosses a ray from w twice anticlockwise and once clockwise, cleanly. What is w(γ, w)?", "a": "1", "w": ["3", "2", "−1"], "why": "Ray-count: 2 − 1."}, {"q": "w(γ, w) = (1/2πi) ∮ dz/(z − w). Which technique?", "a": "winding-total", "w": ["ray-count", "leash", "image-winding"], "why": "The change of ln|z − w| round a closed loop is 0."}, {"q": "p has no root on the circle C, and p(C) winds 3 times round 0. How many roots does p have inside C?", "a": "3, counted with repeats", "w": ["0", "at least 3, maybe more", "1"], "why": "Image-winding technique."}, {"q": "|δ(t) − γ(t)| < |γ(t) − w| for every t. Which technique gives w(δ, w) = w(γ, w)?", "a": "leash", "w": ["ray-count", "winding-total", "image-winding"], "why": "The dog never reaches the post."}, {"q": "z⁵ + 3z + 1 on |z| = 1: |z⁵ + 1| ≤ 2 < 3 = |3z|. How many roots inside?", "a": "1", "w": ["5", "0", "3"], "why": "Leash with owner 3z, which has one root inside."}, {"q": "z⁵ + 3z + 1 on |z| = 2: |3z + 1| ≤ 7 < 32. How many roots inside?", "a": "5", "w": ["1", "4", "3"], "why": "Leash with owner z⁵."}, {"q": "Inside the inner loop of the limaçon (1 + 2cos 2πt)e^{2πit}. What is the winding number?", "a": "2", "w": ["1", "0", "3"], "why": "Both loops go round it."}, {"q": "Two points in the same piece of the plane with the loop taken out. Do they have the same winding number?", "a": "yes: it cannot change without crossing the loop", "w": ["no: it grows with distance", "only if the loop is a circle", "no: it depends on the ray"], "why": "A continuous whole-number count is constant on a piece."}, {"q": "A line reads “count every crossing of the ray as +1”. What is wrong?", "a": "crossings are signed by their direction", "w": ["rays never cross loops", "nothing: all crossings count +1", "only clockwise ones count"], "why": "Anticlockwise +1, clockwise −1."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34m"]=[{"q": "Putting in or taking out a single kink in a drawing. Which move?", "a": "the twist", "w": ["the poke", "the slide", "a pass"], "why": "One crossing of a strand with itself."}, {"q": "Pushing one strand over another, making two crossings. Which move?", "a": "the poke", "w": ["the twist", "the slide", "the mirror"], "why": "Two crossings, in or out."}, {"q": "Moving a strand across a crossing of two others, over both. Which move?", "a": "the slide", "w": ["the poke", "the twist", "an opening"], "why": "Over both or under both."}, {"q": "At every crossing the three strands meeting are all alike or all different. What is the colouring called?", "a": "a three-colouring", "w": ["a bracket", "a writhe", "an opening"], "why": "c(D) counts them."}, {"q": "The overhand knot. What is c, the number of three-colourings?", "a": "9", "w": ["3", "6", "27"], "why": "Three alike and six all-different."}, {"q": "The plain ring. What is c?", "a": "3", "w": ["9", "1", "0"], "why": "One strand, three colours."}, {"q": "A line reads “c(D) = 3, so the knot is the unknot”. What is wrong?", "a": "the figure-eight knot has c = 3 and is knotted", "w": ["c is never 3", "nothing: c = 3 means unknot", "c changes under the poke"], "why": "A count tells knots apart only when it differs."}, {"q": "X(D) = (−s³)^(−w(D)) ⟨D⟩. Why the writhe factor?", "a": "the twist multiplies ⟨D⟩ by −s^(±3)", "w": ["the poke changes ⟨D⟩", "the slide changes ⟨D⟩", "loops add a factor d"], "why": "The writhe changes by ±1 under a twist, undoing it."}, {"q": "X of a knot is not the same with s and s⁻¹ swapped. What follows?", "a": "the knot is not its mirror image", "w": ["the knot is the unknot", "the knot has c = 9", "the knot is its mirror image"], "why": "Mirroring swaps s and s⁻¹."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["34\u00b7cb18"]=[{"q": "Contours every 20 m lie 100 m apart on the ground. What is the slope there?", "a": "about 1 in 5", "w": ["about 5 in 1", "about 1 in 20", "about 1 in 100"], "why": "Spacing-slope: Δ/s = 20/100."}, {"q": "Where contours crowd together on a map, what is the land like?", "a": "steep", "w": ["flat", "a pit", "a pass"], "why": "Small spacing, large Δ/s."}, {"q": "A map is stretched, not torn. What does it keep?", "a": "the contours’ pieces and their nesting", "w": ["the slopes", "the distances", "the contour spacing"], "why": "Stretch-keeps-contours technique."}, {"q": "A flat point where the land looks like x² − y². What is it?", "a": "a pass", "w": ["a peak", "a pit", "a shore"], "why": "Up two ways, down two ways."}, {"q": "A flat point where the land looks like −x² − y². What is it?", "a": "a peak", "w": ["a pit", "a pass", "a shelf"], "why": "Down every way."}, {"q": "An island has 3 peaks and 1 pit. How many passes?", "a": "3", "w": ["4", "2", "1"], "why": "Flood-count: 3 − passes + 1 = 1."}, {"q": "On a whole planet, peaks − passes + pits. What is it?", "a": "2", "w": ["1", "0", "−2"], "why": "The sphere’s characteristic."}, {"q": "A line reads “an island can have two peaks and no pass”. What is wrong?", "a": "2 − 0 + pits = 1 would need −1 pits", "w": ["islands have one peak", "passes are not flat points", "nothing: a ridge suffices"], "why": "Between two summits the route’s lowest high point is a pass."}, {"q": "A hummock too small for the map adds a peak and a pass. What does it do to the count?", "a": "nothing: +1 − 1", "w": ["adds 1", "adds 2", "takes 1"], "why": "Small features come in cancelling pairs."}];
